  ElectricPortrait Portrait(int width,int height,bool hero){return new ElectricPortrait{Width=width,Height=height,Settings=gaze,HeroLayout=hero,CanAnimate=()=>sessionPath==null&&!busy&&WindowState!=FormWindowState.Minimized&&Visible};}
  void Overview(){var p=Page("","");var hero=Portrait(890,370,true);p.Controls.Add(hero);var copy=LabelText("One button strips back Windows effects, notifications, capture and background extras.\r\nYour original settings are saved so you can undo them.",55);copy.ForeColor=Color.FromArgb(195,210,225);p.Controls.Add(copy);p.Controls.Add(Row(Button("OPTIMIZE MY PC",()=>OptimizeOneClick()),Button("Undo changes",()=>ShowPage("Recovery"),false)));p.Controls.Add(LabelText("Uses the aggressive preset. Text can look jagged and some features will be off.\r\nRunning apps and your files stay open. Windows may ask for administrator access.",55));var card=new Panel{Width=890,Height=126,BackColor=panel,Margin=new Padding(0,12,0,8)};adaptiveTitle=new Label{Text="READING YOUR PC",Location=new Point(18,14),Width=820,Height=28,ForeColor=accent,Font=new Font("Consolas",13,FontStyle.Bold)};adaptiveText=new Label{Text="Checking CPU, RAM and drive space.",Location=new Point(18,46),Width=620,Height=55,ForeColor=muted};var next=Button("See next step",()=>ShowPage(adaptivePage),false);next.Location=new Point(650,62);next.Width=215;card.Controls.Add(adaptiveTitle);card.Controls.Add(adaptiveText);card.Controls.Add(next);p.Controls.Add(card);p.Controls.Add(LabelText("FREE. NO ADS. NO MADE-UP BOOST SCORE.\r\nKeep the changes that help. Undo the rest.",54));TickStatus();}
  void LookPage(){var p=Page("Your face. Your look.","A live 2D raster effect built from your portrait. It pauses during game mode and when the app is minimized. It runs at up to 10 frames per second and slows down for costly effects.");var row=new Panel{Width=890,Height=375};var art=Portrait(280,370,false);row.Controls.Add(art);var options=new FlowLayoutPanel{Location=new Point(310,0),Width=560,Height=370,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};row.Controls.Add(options);var mode=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};mode.Items.AddRange(ElectricGaze.Modes.Cast<object>().ToArray());mode.SelectedItem=gaze.renderMode;options.Controls.Add(new Label{Text="Pattern",Width=420,Height=24});options.Controls.Add(mode);mode.SelectedIndexChanged+=(s,e)=>{gaze.renderMode=mode.Text;art.RenderFrame();};var animation=new CheckBox{Text="Animate the portrait",Checked=gaze.animated,Width=420,Height=34};animation.CheckedChanged+=(s,e)=>{gaze.animated=animation.Checked;art.RenderFrame();};options.Controls.Add(animation);var style=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};style.Items.AddRange(new object[]{"wave","pulse","shimmer","ripple","flicker"});style.SelectedItem=gaze.animStyle;style.SelectedIndexChanged+=(s,e)=>{gaze.animStyle=style.Text;art.RenderFrame();};options.Controls.Add(style);options.Controls.Add(Slider("Cell size",2,24,gaze.cellSize,value=>{gaze.cellSize=value;art.RenderFrame();}));options.Controls.Add(Slider("Contrast",-100,200,(int)gaze.contrast,value=>{gaze.contrast=value;art.RenderFrame();}));options.Controls.Add(Slider("Amount of detail",0,100,(int)gaze.density,value=>{gaze.density=value;art.RenderFrame();}));var fx=new CheckedListBox{Width=420,Height=95,CheckOnClick=true,BackColor=panel,ForeColor=Color.White};foreach(string key in gaze.pfx.Keys)fx.Items.Add(key,gaze.pfx[key].enabled);fx.ItemCheck+=(s,e)=>{gaze.pfx[(string)fx.Items[e.Index]].enabled=e.NewValue==CheckState.Checked;BeginInvoke((Action)(()=>art.RenderFrame()));};options.Controls.Add(fx);p.Controls.Add(row);p.Controls.Add(Row(Button("Save effect JSON",()=>{using(var dialog=new SaveFileDialog{Filter="Effect settings|*.json",FileName="Electric-Gaze.json"})if(dialog.ShowDialog(this)==DialogResult.OK)Store.Save(dialog.FileName,gaze);}),Button("Load effect JSON",()=>{using(var dialog=new OpenFileDialog{Filter="Effect settings|*.json"})if(dialog.ShowDialog(this)==DialogResult.OK){try{var loaded=Store.Load<GazeSettings>(dialog.FileName);if(!ElectricGaze.Modes.Contains(loaded.renderMode))throw new Exception("Unknown pattern");using(var test=ElectricGaze.Render(new Bitmap(16,16),64,64,loaded,0)){}gaze=loaded;ShowPage("Your look");}catch(Exception ex){Log("Effect file: "+ex.Message);}}})));p.Controls.Add(Button("Export this frame",()=>{using(var dialog=new SaveFileDialog{Filter="PNG image|*.png",FileName="Electric-Gaze.png"})if(dialog.ShowDialog(this)==DialogResult.OK){using(var stream=typeof(ElectricPortrait).Assembly.GetManifestResourceStream("Overdrive.Portrait"))using(var source=Image.FromStream(stream))using(var image=ElectricGaze.Render(source,600,840,gaze,2))image.Save(dialog.FileName,System.Drawing.Imaging.ImageFormat.Png);}}));p.Controls.Add(LabelText("The JSON file gives you full control over colors, blur, glow, masks and effects. Your portrait is built into this preview. The app uploads nothing.",60));}
  Control Slider(string name,int min,int max,int value,Action<int> changed){var row=new Panel{Width=430,Height=65};var label=new Label{Text=name+" · "+value,Width=420,Height=23};var slider=new TrackBar{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,value)),Width=420,Height=36,Top=24,TickStyle=TickStyle.None};slider.ValueChanged+=(s,e)=>{label.Text=name+" · "+slider.Value;changed(slider.Value);};row.Controls.Add(label);row.Controls.Add(slider);return row;}
 }
